<?php
declare(strict_types=1);
require_once __DIR__.'/app.php';
$id=filter_input(INPUT_GET,'id',FILTER_VALIDATE_INT);$token=trim((string)($_GET['t']??''));
if(!$id||!verify_gallery_token($id,$token)){http_response_code(404);exit('Anúncio não encontrado.');}
try{$rows=supabase_request('GET','/rest/v1/imoveis?select=*&id=eq.'.$id.'&limit=1');$imovel=$rows[0]??null;$perfil=profile_data();}catch(Throwable){http_response_code(500);exit('Não foi possível carregar o anúncio.');}
if(!$imovel){http_response_code(404);exit('Anúncio não encontrado.');}
$fotos=is_array($imovel['fotos']??null)?$imovel['fotos']:[];$fotos=array_values(array_filter($fotos,fn($f)=>is_array($f)&&!empty($f['url'])));
$showLocation=isset($_GET['localizacao'])&&$_GET['localizacao']==='1'&&!empty($imovel['latitude'])&&!empty($imovel['longitude']);
$features=[];foreach([[(int)($imovel['capacidade']??0),'pessoas'],[(int)($imovel['dormitorios']??0),'dormitórios'],[(int)($imovel['suites']??0),'suítes']] as $f){if($f[0]>0)$features[]=$f[0].' '.$f[1];}foreach([['piscina','Piscina'],['churrasqueira','Churrasqueira'],['ar_condicionado','Ar-condicionado']] as $f){if(!empty($imovel[$f[0]]))$features[]=$f[1];}
$shareBase=gallery_url($id);$urlNo=$shareBase.'&anuncio=1&localizacao=0';$urlYes=$shareBase.'&anuncio=1&localizacao=1';
?>
